{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "حينئذ تظهر جبانة العذاب، وبجانبها موضع الراحة، ويوضح أتون جهنم، وبجانبها فردوس اللذة.",
      "verse": 36
    },
    {
      "chapter": 7,
      "text_ar": "حينئذ يقول العلي للأمم المقامة من الأموات: انظروا وافهموا من الذي أنكرتموه، ومن الذي لم تعبدوه، ومن الذي احتقرتم وصاياه.",
      "verse": 37
    },
    {
      "chapter": 7,
      "text_ar": "انظروا إلى هنا وإلى هناك: ههنا اللذة والراحة، وهناك النار والعذاب. هكذا كلمهم في يوم الدين.",
      "verse": 38
    },
    {
      "chapter": 7,
      "text_ar": "وهذا هو اليوم الذي ليس فيه شمس ولا قمر ولا كواكب،",
      "verse": 39
    },
    {
      "chapter": 7,
      "text_ar": "ولا سحاب ولا رعد ولا برق ولا ريح ولا ماء ولا هواء ولا ظلام ولا مساء ولا صباح.",
      "verse": 40
    }
  ]
}
